package net.officefloor.hq.app;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

/** Data access for {@link Invoice}. A Spring bean, injected into the OfficeFloor logic classes. */
public interface InvoiceRepository extends JpaRepository<Invoice, Long> {

    /** A project's invoices, oldest first, so the list is stable across loads. */
    List<Invoice> findByProjectIdOrderByIdAsc(Long projectId);

    /** A project's invoices, earliest due date first (id as a stable tie-breaker). */
    List<Invoice> findByProjectIdOrderByDueDateAscIdAsc(Long projectId);

    /** Every invoice with the given status (e.g. UNPAID), oldest first — used to total what is owed. */
    List<Invoice> findByStatusOrderByIdAsc(String status);
}
===== ListInvoicesLogic.java =====
package net.officefloor.hq.app;

import java.util.List;
import java.util.stream.Collectors;
import net.officefloor.web.HttpPathParameter;
import net.officefloor.web.HttpQueryParameter;
import net.officefloor.web.ObjectResponse;

/**
 * GET /api/projects/{projectId}/invoices — a project's invoices. Ordered oldest first by default;
 * {@code ?sort=due} orders them by their due date, earliest first (id as a stable tie-breaker).
 */
public class ListInvoicesLogic {

    public void service(@HttpPathParameter("projectId") String projectId,
            @HttpQueryParameter("sort") String sort, InvoiceRepository invoices,
            ObjectResponse<List<InvoiceView>> response) {
        Long id = Long.valueOf(projectId);
        List<Invoice> ordered = "due".equals(sort)
                ? invoices.findByProjectIdOrderByDueDateAscIdAsc(id)
                : invoices.findByProjectIdOrderByIdAsc(id);
        List<InvoiceView> views = ordered.stream()
                .map(inv -> new InvoiceView(inv.getId(), inv.getProjectId(), inv.getAmount(), inv.getStatus(),
                        inv.getIssuedDate() == null ? null : inv.getIssuedDate().toString(),
                        inv.getDueDate() == null ? null : inv.getDueDate().toString()))
                .collect(Collectors.toList());
        response.send(views);
    }
}
===== PayInvoiceLogic.java =====
package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.math.RoundingMode;
import net.officefloor.server.http.HttpException;
import net.officefloor.server.http.HttpStatus;
import net.officefloor.web.HttpPathParameter;
import net.officefloor.web.ObjectResponse;

/**
 * POST /api/invoices/{invoiceId}/pay — mark an invoice PAID and record the transition. Flips the
 * invoice's status to PAID, then appends one audit record (INVOICE_PAID id=&lt;id&gt; amount=&lt;amount&gt;)
 * so the owner can check back later. An unknown invoice is rejected with 400 and nothing is written.
 */
public class PayInvoiceLogic {

    public void service(@HttpPathParameter("invoiceId") String invoiceId,
            InvoiceRepository invoices, Audit audit, ObjectResponse<InvoiceView> response) {
        Long id = Long.valueOf(invoiceId);
        Invoice invoice = invoices.findById(id).orElseThrow(
                () -> new HttpException(HttpStatus.BAD_REQUEST, "An existing invoice is required"));
        invoice.setStatus("PAID");
        Invoice saved = invoices.save(invoice);
        BigDecimal amount = saved.getAmount().setScale(2, RoundingMode.HALF_UP);
        audit.record("INVOICE_PAID id=" + saved.getId() + " amount=" + amount.toPlainString());
        response.send(new InvoiceView(saved.getId(), saved.getProjectId(), saved.getAmount(), saved.getStatus(),
                saved.getIssuedDate() == null ? null : saved.getIssuedDate().toString(),
                saved.getDueDate() == null ? null : saved.getDueDate().toString()));
    }
}
===== CreateInvoiceLogic.java =====
package net.officefloor.hq.app;

import java.math.BigDecimal;
import net.officefloor.server.http.HttpException;
import net.officefloor.server.http.HttpStatus;
import net.officefloor.web.HttpPathParameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * POST /api/projects/{projectId}/invoices — add an invoice for the given amount to an existing
 * project, echo back the saved row. A missing amount or an unknown project is rejected with 400 and
 * never persisted.
 */
public class CreateInvoiceLogic {

    public void service(@HttpPathParameter("projectId") String projectId,
            @RequestBody NewInvoice newInvoice, ProjectRepository projects,
            InvoiceRepository invoices, ObjectResponse<InvoiceView> response) {
        BigDecimal amount = newInvoice.getAmount();
        if (amount == null) {
            throw new HttpException(HttpStatus.BAD_REQUEST, "An amount is required");
        }
        if (amount.compareTo(BigDecimal.ZERO) <= 0) {
            throw new HttpException(HttpStatus.BAD_REQUEST, "An amount greater than zero is required");
        }
        Long id = Long.valueOf(projectId);
        projects.findById(id).orElseThrow(
                () -> new HttpException(HttpStatus.BAD_REQUEST, "An existing project is required"));
        Invoice saved = invoices.save(new Invoice(id, amount));
        response.send(new InvoiceView(saved.getId(), saved.getProjectId(), saved.getAmount(), saved.getStatus(),
                saved.getIssuedDate() == null ? null : saved.getIssuedDate().toString(),
                saved.getDueDate() == null ? null : saved.getDueDate().toString()));
    }
}
